import { debounce } from 'lodash-es';
import { useCallback, useRef, useState } from 'react';

import { isMouseOutsideElement } from '../../../functions/is-mouse-outside-element.js';

const DEBOUNCE_TIME_MS = 5;

/**
 * @internal
 */
export function useChartActionsMenu() {
  const [selectedItem, setSelectedItem] = useState<string>('');
  const [isScrolling, setIsScrolling] = useState(false);
  const actionsMenuRef = useRef<HTMLDivElement>(null);

  const onLeave = (evt: React.MouseEvent) => {
    if (!evt || isMouseOutsideElement(evt, actionsMenuRef)) {
      setSelectedItem('');
    }
  };

  const onScrollEnd = debounce(() => setIsScrolling(false), DEBOUNCE_TIME_MS);

  const onScroll = (evt: Event) => {
    setSelectedItem('');
    setIsScrolling(true);
    onScrollEnd();
  };

  const onUpdateSelectedItem = useCallback(
    (itemId: string) => {
      if (selectedItem !== itemId) {
        setSelectedItem(itemId);
      }
    },
    [selectedItem],
  );

  return {
    selectedItem,
    isScrolling,
    onLeave,
    onScroll,
    updateSelectedItem: onUpdateSelectedItem,
    actionsMenuRef,
  };
}
